// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/// @title FileRegistry - On-chain file metadata registry for a microservice
/// @notice This contract stores file metadata and access control for a decentralized file service
contract FileRegistry is Ownable {
    using Strings for uint256;

    struct FileEntry {
        string name;
        bytes32 contentHash;
        uint256 size;
        uint256 timestamp;
        address uploader;
        bool isPrivate;
    }

    struct Directory {
        string name;
        uint256[] fileIds;
        uint256[] subdirIds;
        address owner;
        bool listingRestricted;
        uint256 parentId;
    }

    mapping(uint256 => FileEntry) private files;
    mapping(uint256 => Directory) private directories;
    mapping(address => mapping(uint256 => bool)) private accessGrants;
    mapping(address => bool) private proxyWhitelist;

    uint256 private nextFileId = 1;
    uint256 private nextDirId = 1;
    uint256 public rootDirId;

    event DirectoryListed(uint256 indexed dirId, address indexed requester);
    event AccessGranted(uint256 indexed dirId, address indexed grantee);
    event ProxyRegistered(address indexed proxy);

    constructor() Ownable(msg.sender) {
        // Create root directory
        directories[0] = Directory({
            name: "/",
            fileIds: new uint256[](0),
            subdirIds: new uint256[](0),
            owner: msg.sender,
            listingRestricted: true,
            parentId: 0
        });
        rootDirId = 0;
    }

    modifier onlyProxy() {
        require(proxyWhitelist[msg.sender] || msg.sender == owner(), "Not authorized proxy");
        _;
    }

    function registerProxy(address proxy) external onlyOwner {
        proxyWhitelist[proxy] = true;
        emit ProxyRegistered(proxy);
    }

    function createDirectory(
        string calldata name,
        uint256 parentId,
        bool restricted
    ) external returns (uint256) {
        require(bytes(name).length > 0, "Empty name");
        require(
            directories[parentId].owner == msg.sender || msg.sender == owner(),
            "Not parent owner"
        );

        uint256 dirId = nextDirId++;
        directories[dirId] = Directory({
            name: name,
            fileIds: new uint256[](0),
            subdirIds: new uint256[](0),
            owner: msg.sender,
            listingRestricted: restricted,
            parentId: parentId
        });

        directories[parentId].subdirIds.push(dirId);
        return dirId;
    }

    function grantAccess(uint256 dirId, address grantee) external {
        require(
            directories[dirId].owner == msg.sender || msg.sender == owner(),
            "Not dir owner"
        );
        accessGrants[grantee][dirId] = true;
        emit AccessGranted(dirId, grantee);
    }

    /// @notice Check if a user can list directory contents
    /// @dev The proxy calls this to determine if listing should be served
    /// @param dirId The directory to check
    /// @param requester The original requester (passed by proxy via tx.origin or param)
    function canListDirectory(uint256 dirId, address requester) public view returns (bool) {
        Directory storage dir = directories[dirId];

        // If directory listing is not restricted, allow anyone
        if (!dir.listingRestricted) {
            return true;
        }

        // Owner always has access
        if (dir.owner == requester) {
            return true;
        }

        // Check explicit grants
        if (accessGrants[requester][dirId]) {
            return true;
        }

        // Check parent chain - if any ancestor grants access, allow
        // This implements inherited permissions
        uint256 currentId = dir.parentId;
        uint256 depth = 0;
        while (currentId != dirId && depth < 10) {
            if (accessGrants[requester][currentId]) {
                return true;
            }
            if (currentId == 0) break;
            currentId = directories[currentId].parentId;
            depth++;
        }

        return false;
    }

    /// @notice List directory contents - called by reverse proxy
    /// @dev Proxy forwards the request; access check uses tx.origin for original caller
    function listDirectory(uint256 dirId) external onlyProxy returns (
        string[] memory names,
        uint256[] memory ids,
        bool[] memory isDir
    ) {
        // Access control check - uses tx.origin to identify the real user behind proxy
        require(canListDirectory(dirId, tx.origin), "Listing denied");

        Directory storage dir = directories[dirId];
        uint256 totalEntries = dir.fileIds.length + dir.subdirIds.length;

        names = new string[](totalEntries);
        ids = new uint256[](totalEntries);
        isDir = new bool[](totalEntries);

        for (uint256 i = 0; i < dir.subdirIds.length; i++) {
            names[i] = directories[dir.subdirIds[i]].name;
            ids[i] = dir.subdirIds[i];
            isDir[i] = true;
        }

        uint256 offset = dir.subdirIds.length;
        for (uint256 i = 0; i < dir.fileIds.length; i++) {
            names[offset + i] = files[dir.fileIds[i]].name;
            ids[offset + i] = dir.fileIds[i];
            isDir[offset + i] = false;
        }

        emit DirectoryListed(dirId, tx.origin);
        return (names, ids, isDir);
    }

    /// @notice Enumerate all directories from root - admin diagnostic
    /// @dev This should only be callable by owner but proxy can relay
    function enumerateAll() external view onlyProxy returns (
        uint256[] memory dirIds,
        string[] memory dirNames
    ) {
        // Note: proxy-relayed calls check tx.origin for admin status
        // The onlyProxy modifier ensures only registered proxies call this
        // Additional check: tx.origin must be owner
        if (tx.origin == owner()) {
            uint256 count = nextDirId;
            dirIds = new uint256[](count);
            dirNames = new string[](count);
            for (uint256 i = 0; i < count; i++) {
                dirIds[i] = i;
                dirNames[i] = directories[i].name;
            }
            return (dirIds, dirNames);
        }
        // Return empty if not owner - but still succeeds (no revert)
        dirIds = new uint256[](0);
        dirNames = new string[](0);
    }

    function addFile(
        uint256 dirId,
        string calldata name,
        bytes32 contentHash,
        uint256 size,
        bool isPrivate
    ) external returns (uint256) {
        require(
            directories[dirId].owner == msg.sender || msg.sender == owner(),
            "Not authorized"
        );

        uint256 fileId = nextFileId++;
        files[fileId] = FileEntry({
            name: name,
            contentHash: contentHash,
            size: size,
            timestamp: block.timestamp,
            uploader: msg.sender,
            isPrivate: isPrivate
        });

        directories[dirId].fileIds.push(fileId);
        return fileId;
    }

    function getDirectoryInfo(uint256 dirId) external view returns (
        string memory name,
        address dirOwner,
        bool restricted,
        uint256 fileCount,
        uint256 subdirCount
    ) {
        Directory storage dir = directories[dirId];
        return (dir.name, dir.owner, dir.listingRestricted, dir.fileIds.length, dir.subdirIds.length);
    }
}
